class Solution:
    def minIncreaseSpecialIndices(self, nums):
        n = len(nums)
        def better(a, b):
            if a[0] != b[0]:
                return a if a[0] > b[0] else b
            return a if a[1] <= b[1] else b
        prev2 = (0, 0)
        prev1 = (0, 0)
        for i in range(n):
            take = (0, 0)
            if 0 < i < n - 1:
                c = max(0, max(nums[i-1], nums[i+1]) + 1 - nums[i])
                take = (prev2[0] + 1, prev2[1] + c)
            cur = better(prev1, take)
            prev2, prev1 = prev1, cur
        return prev1[1]

