public:
    long long minIncreaseSpecialIndices(vector<int>& nums) {
        int n = nums.size();
        pair<long long,long long> prev2 = {0, 0}, prev1 = {0, 0};
        for (int i = 0; i < n; i++) {
            pair<long long,long long> take = {0, 0};
            if (i > 0 && i < n - 1) {
                long long c = max(0LL, (long long)max(nums[i-1], nums[i+1]) + 1 - nums[i]);
                take = {prev2.first + 1, prev2.second + c};
            }
            pair<long long,long long> cur =
                (prev1.first != take.first) ? max(prev1, take) :
                (prev1.second <= take.second ? prev1 : take);
            prev2 = prev1; prev1 = cur;
        }
        return prev1.second;
    }
};

